import type { ReactNode } from "react";

export type CanvasNodeVisualStatusTone =
  | "negative"
  | "neutral"
  | "positive"
  | "progress"
  | "warning";

export interface CanvasNodeStatus {
  label: string;
  visualTone?: CanvasNodeVisualStatusTone;
}

export interface CanvasNodeInteractionState {
  connectable?: boolean;
  dragging?: boolean;
  highlightedConnectionSide?: CanvasNodeConnectionSide;
  selected?: boolean;
}

/** Visual side identifier used for connection handle placement and card-edge hover glow. */
export type CanvasNodeConnectionSide = "bottom" | "left" | "right" | "top";

export interface CanvasNodeState {
  interaction?: CanvasNodeInteractionState;
}

export interface CanvasNodeActions {
  collapse?: () => void;
  expand?: () => void;
}

export interface CanvasNodeMeta {
  expanded: boolean;
}

export interface CanvasNodeContextValue {
  actions: Required<Pick<CanvasNodeActions, "collapse" | "expand">> &
    Omit<CanvasNodeActions, "collapse" | "expand">;
  meta: CanvasNodeMeta;
  state: CanvasNodeState;
}

export interface CanvasNodeProviderProps {
  children?: ReactNode;
  value: CanvasNodeContextValue;
}

export interface CanvasNodeRootProps {
  children?: ReactNode;
  defaultExpanded?: boolean;
  expanded?: boolean;
  interaction?: CanvasNodeInteractionState;
  onExpandedChange?: (expanded: boolean) => void;
}

import type { CanvasNodeAction } from "./canvas-node.actions";

/** Lifecycle verbs shared by canvas resource node menus. */
export type CanvasNodeLifecycleVerb = "delete" | "restart" | "start" | "stop";

/**
 * State-resolved presentation for one resource affordance entry.
 *
 * `present: false` removes the entry entirely — reserved for verbs that are
 * structurally inapplicable in the current state (Start while running, Stop or
 * Restart while stopped). A `disabledReason` keeps the entry visible as an
 * unavailable affordance with a user-facing reason. `inFlight` marks a verb
 * observed in progress, presented as a disabled spinner.
 */
export interface CanvasNodeActionAvailability {
  disabledReason?: string;
  inFlight?: boolean;
  present: boolean;
}

export type CanvasNodeLifecycleAvailability = Record<
  CanvasNodeLifecycleVerb,
  CanvasNodeActionAvailability
>;

export const CANVAS_NODE_FAILED_TONES: ReadonlySet<string> = new Set([
  "degraded",
  "error",
  "failed",
  "inaccessible",
  "unavailable",
  "unhealthy",
]);

export const CANVAS_NODE_RUNNING_TONES: ReadonlySet<string> = new Set([
  "available",
  "bound",
  "complete",
  "ready",
  "running",
  "succeeded",
]);

export const CANVAS_NODE_STOPPED_TONES: ReadonlySet<string> = new Set([
  "paused",
  "shutdown",
  "stopped",
  "suspended",
]);

/** Transient tones without a lifecycle verb of their own. */
export const CANVAS_NODE_BUSY_TONES: ReadonlySet<string> = new Set([
  "binding",
  "creating",
  "pending",
  "progressing",
  "reconciling",
  "updating",
]);

export function normalizeCanvasNodeStatusTone(
  input: string | undefined
): string | undefined {
  const normalized = input
    ?.trim()
    .toLowerCase()
    .replace(/[\s_]+/g, "-");
  return normalized === "" ? undefined : normalized;
}

const PRESENT: CanvasNodeActionAvailability = { present: true };
const HIDDEN: CanvasNodeActionAvailability = { present: false };
const IN_FLIGHT: CanvasNodeActionAvailability = {
  inFlight: true,
  present: true,
};

function unavailable(disabledReason: string): CanvasNodeActionAvailability {
  return { disabledReason, present: true };
}

/**
 * Resolves lifecycle menu entries from the workload status tone.
 *
 * Mutually exclusive verbs resolve away (hidden); anything conceptually
 * applicable but unusable right now stays visible with a reason. The in-flight
 * verb of a transient state is echoed with a spinner. `noun` is the
 * user-facing resource word used in reasons (for example "Workload" or
 * "Database").
 */
export function canvasNodeLifecycleAvailability(
  tone: string | undefined,
  noun: string
): CanvasNodeLifecycleAvailability {
  const normalized = normalizeCanvasNodeStatusTone(tone);

  if (normalized === "starting") {
    return {
      delete: PRESENT,
      restart: unavailable(`${noun} is starting.`),
      start: IN_FLIGHT,
      stop: HIDDEN,
    };
  }
  if (normalized === "stopping") {
    return {
      delete: PRESENT,
      restart: unavailable(`${noun} is stopping.`),
      start: HIDDEN,
      stop: IN_FLIGHT,
    };
  }
  if (normalized === "restarting") {
    return {
      delete: PRESENT,
      restart: IN_FLIGHT,
      start: HIDDEN,
      stop: unavailable(`${noun} is restarting.`),
    };
  }
  if (normalized === "deleting") {
    const reason = `${noun} is being deleted.`;
    return {
      delete: IN_FLIGHT,
      restart: unavailable(reason),
      start: HIDDEN,
      stop: unavailable(reason),
    };
  }
  if (
    normalized != null &&
    (CANVAS_NODE_RUNNING_TONES.has(normalized) ||
      CANVAS_NODE_FAILED_TONES.has(normalized))
  ) {
    return { delete: PRESENT, restart: PRESENT, start: HIDDEN, stop: PRESENT };
  }
  if (normalized != null && CANVAS_NODE_STOPPED_TONES.has(normalized)) {
    return { delete: PRESENT, restart: HIDDEN, start: PRESENT, stop: HIDDEN };
  }
  if (normalized != null && CANVAS_NODE_BUSY_TONES.has(normalized)) {
    const reason = `${noun} is busy right now.`;
    return {
      delete: PRESENT,
      restart: unavailable(reason),
      start: HIDDEN,
      stop: unavailable(reason),
    };
  }

  const reason = `${noun} state is unknown.`;
  return {
    delete: PRESENT,
    restart: unavailable(reason),
    start: HIDDEN,
    stop: unavailable(reason),
  };
}

/**
 * Overlays state availability onto a host-provided action. Host-provided
 * (session-level) reasons win over state reasons; an observed in-flight verb
 * always presents as loading.
 */
export function canvasNodeActionWithAvailability(
  action: CanvasNodeAction | undefined,
  availability: CanvasNodeActionAvailability
): CanvasNodeAction {
  const disabledReason = action?.disabledReason ?? availability.disabledReason;
  return {
    ...action,
    disabled: Boolean(
      action?.disabled ||
        availability.disabledReason != null ||
        availability.inFlight
    ),
    ...(disabledReason === undefined ? {} : { disabledReason }),
    loading: Boolean(action?.loading || availability.inFlight),
  };
}

/**
 * Per-node subscription store for the masked glass sheet. The sheet
 * controller writes one snapshot per animation frame; each node surface
 * subscribes by id and re-renders only when its own self-blur decision flips.
 * Mirrors the interaction-store pattern so facts flow through a store, never
 * through node data or per-frame className churn (ADR-0035).
 */

export interface CanvasGlassSnapshot {
  /** True while a shared sheet is mounted and handling isolated nodes. */
  active: boolean;
  /** Ids of nodes that currently overlap another node. */
  overlapping: ReadonlySet<string>;
}

export interface CanvasGlassStore {
  getNodeSelfBlur(nodeId: string): boolean;
  setSnapshot(snapshot: CanvasGlassSnapshot): void;
  subscribeNode(nodeId: string, listener: () => void): () => void;
}

const INACTIVE_SNAPSHOT: CanvasGlassSnapshot = {
  active: false,
  overlapping: new Set(),
};

/**
 * A node paints its own backdrop-filter when there is no active sheet, or when
 * it overlaps another node (the shared sheet can't blur one node behind
 * another). Otherwise the sheet blurs under it and the node drops its own blur.
 */
export function selectCanvasNodeSelfBlur(
  snapshot: CanvasGlassSnapshot,
  nodeId: string
): boolean {
  return !snapshot.active || snapshot.overlapping.has(nodeId);
}

/**
 * Ids whose self-blur decision differs between two snapshots. Overlap
 * membership changes touch the nodes entering/leaving overlap; an `active` flip
 * can change every tracked node, so those are all candidates.
 */
function canvasGlassAffectedNodeIds(
  before: CanvasGlassSnapshot,
  after: CanvasGlassSnapshot,
  tracked: Iterable<string>
): Set<string> {
  const candidates = new Set<string>();
  for (const id of before.overlapping) {
    candidates.add(id);
  }
  for (const id of after.overlapping) {
    candidates.add(id);
  }
  if (before.active !== after.active) {
    for (const id of tracked) {
      candidates.add(id);
    }
  }
  const affected = new Set<string>();
  for (const id of candidates) {
    if (
      selectCanvasNodeSelfBlur(before, id) !==
      selectCanvasNodeSelfBlur(after, id)
    ) {
      affected.add(id);
    }
  }
  return affected;
}

export function createCanvasGlassStore(
  initialSnapshot: CanvasGlassSnapshot = INACTIVE_SNAPSHOT
): CanvasGlassStore {
  let snapshot = initialSnapshot;
  const subscribersByNodeId = new Map<string, Set<() => void>>();
  const selfBlurByNodeId = new Map<string, boolean>();

  return {
    getNodeSelfBlur(nodeId) {
      const cached = selfBlurByNodeId.get(nodeId);
      if (cached !== undefined) {
        return cached;
      }
      const selfBlur = selectCanvasNodeSelfBlur(snapshot, nodeId);
      selfBlurByNodeId.set(nodeId, selfBlur);
      return selfBlur;
    },
    setSnapshot(nextSnapshot) {
      const affectedNodeIds = canvasGlassAffectedNodeIds(
        snapshot,
        nextSnapshot,
        selfBlurByNodeId.keys()
      );
      snapshot = nextSnapshot;
      for (const nodeId of affectedNodeIds) {
        const selfBlur = selectCanvasNodeSelfBlur(snapshot, nodeId);
        if (selfBlurByNodeId.get(nodeId) === selfBlur) {
          continue;
        }
        selfBlurByNodeId.set(nodeId, selfBlur);
        for (const listener of subscribersByNodeId.get(nodeId) ?? []) {
          listener();
        }
      }
    },
    subscribeNode(nodeId, listener) {
      const subscribers = subscribersByNodeId.get(nodeId) ?? new Set();
      subscribers.add(listener);
      subscribersByNodeId.set(nodeId, subscribers);
      return () => {
        subscribers.delete(listener);
        if (subscribers.size === 0) {
          subscribersByNodeId.delete(nodeId);
          selfBlurByNodeId.delete(nodeId);
        }
      };
    },
  };
}

"use client";

import {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useSyncExternalStore,
} from "react";
import {
  type CanvasGlassStore,
  createCanvasGlassStore,
} from "./canvas-glass-store";

const CanvasGlassStoreContext = createContext<CanvasGlassStore | null>(null);

/** Default store for subtrees without a sheet: every node keeps its own blur. */
const EMPTY_STORE = createCanvasGlassStore();

export function CanvasGlassStoreProvider({
  children,
  store,
}: {
  children: ReactNode;
  store: CanvasGlassStore | null;
}) {
  return (
    <CanvasGlassStoreContext value={store ?? EMPTY_STORE}>
      {children}
    </CanvasGlassStoreContext>
  );
}

/**
 * Whether this node should paint its own `backdrop-filter`. True (keep blur)
 * when there is no active sheet or when the node overlaps another node; false
 * when the shared sheet blurs under it. `null` nodeId (rendered outside a React
 * Flow node) keeps blur, preserving standalone/preview usage.
 */
export function useCanvasNodeSelfBlur(nodeId: string | null): boolean {
  const store = useContext(CanvasGlassStoreContext) ?? EMPTY_STORE;
  const subscribe = useCallback(
    (listener: () => void) =>
      nodeId == null ? () => undefined : store.subscribeNode(nodeId, listener),
    [nodeId, store]
  );
  const getSnapshot = useCallback(
    () => (nodeId == null ? true : store.getNodeSelfBlur(nodeId)),
    [nodeId, store]
  );
  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

"use client";

import { createContext, use } from "react";

import type { CanvasNodeContextValue } from "./canvas-node.types";

export const CanvasNodeContext = createContext<CanvasNodeContextValue | null>(
  null
);

export function useCanvasNode(): CanvasNodeContextValue {
  const value = use(CanvasNodeContext);

  if (!value) {
    throw new Error(
      "CanvasNode: compound components must be used within CanvasNode.Root"
    );
  }

  return value;
}

"use client";

import { CanvasNodeContext } from "./canvas-node.context";
import type { CanvasNodeProviderProps } from "./canvas-node.types";

export function CanvasNodeProvider({
  children,
  value,
}: CanvasNodeProviderProps) {
  return <CanvasNodeContext value={value}>{children}</CanvasNodeContext>;
}

"use client";

import { useCallback, useMemo, useState } from "react";

import { CanvasNodeProvider } from "./canvas-node.provider";
import type {
  CanvasNodeContextValue,
  CanvasNodeRootProps,
} from "./canvas-node.types";

export function CanvasNodeRoot({
  children,
  defaultExpanded = false,
  expanded,
  interaction,
  onExpandedChange,
}: CanvasNodeRootProps) {
  const [internalExpanded, setInternalExpanded] = useState(defaultExpanded);
  const expandedControlled = expanded !== undefined;
  const resolvedExpanded = expanded ?? internalExpanded;

  const setExpandedState = useCallback(
    (nextExpanded: boolean) => {
      if (!expandedControlled) {
        setInternalExpanded(nextExpanded);
      }

      onExpandedChange?.(nextExpanded);
    },
    [expandedControlled, onExpandedChange]
  );

  const collapse = useCallback(() => {
    setExpandedState(false);
  }, [setExpandedState]);

  const expand = useCallback(() => {
    setExpandedState(true);
  }, [setExpandedState]);

  const value = useMemo(
    (): CanvasNodeContextValue => ({
      actions: {
        collapse,
        expand,
      },
      meta: {
        expanded: resolvedExpanded,
      },
      state: {
        interaction,
      },
    }),
    [collapse, expand, interaction, resolvedExpanded]
  );

  return <CanvasNodeProvider value={value}>{children}</CanvasNodeProvider>;
}

"use client";

import { cn } from "@workspace/ui/lib/utils";
import type { PointerEvent, ReactNode } from "react";
import { useCallback, useEffect, useRef, useState } from "react";

import { useCanvasNode } from "./canvas-node.context";

const HOVER_HIDE_DELAY_MS = 100;
const HOVER_ZONE_SELECTOR = [
  '[data-slot="canvas-node-surface"]',
  '[data-slot="canvas-node-expand-button"]',
  '[data-slot="canvas-node-rf-handle"]',
].join(",");

type CanvasNodeHoverZone = "connection" | "expand-control" | "surface";

function getCanvasNodeHoverZone(
  currentTarget: HTMLElement,
  target: EventTarget | null
): CanvasNodeHoverZone | null {
  if (!(target instanceof Element)) {
    return null;
  }

  const hoverEl = target.closest(HOVER_ZONE_SELECTOR);

  if (!(hoverEl instanceof HTMLElement && currentTarget.contains(hoverEl))) {
    return null;
  }

  switch (hoverEl.dataset.slot) {
    case "canvas-node-rf-handle":
      return "connection";
    case "canvas-node-expand-button":
      return "expand-control";
    case "canvas-node-surface":
      return "surface";
    default:
      return null;
  }
}

export function CanvasNodeFrame({
  children,
  className,
}: {
  children?: ReactNode;
  className?: string;
}) {
  const {
    meta: { expanded },
    state: { interaction },
  } = useCanvasNode();
  const selected = interaction?.selected ?? false;
  const dragging = interaction?.dragging ?? false;
  const connectable = interaction?.connectable ?? true;
  const highlightedConnectionSide = interaction?.highlightedConnectionSide;
  const [hoverIntent, setHoverIntent] = useState(false);
  const hoverIntentRef = useRef(false);
  const hoverIntentTimerRef = useRef<ReturnType<typeof setTimeout> | null>(
    null
  );

  const setResolvedHoverIntent = useCallback((nextHoverIntent: boolean) => {
    hoverIntentRef.current = nextHoverIntent;
    setHoverIntent((currentHoverIntent) =>
      currentHoverIntent === nextHoverIntent
        ? currentHoverIntent
        : nextHoverIntent
    );
  }, []);

  const clearHoverIntentTimer = useCallback(() => {
    if (!hoverIntentTimerRef.current) {
      return;
    }

    clearTimeout(hoverIntentTimerRef.current);
    hoverIntentTimerRef.current = null;
  }, []);

  const showHoverIntent = useCallback(() => {
    clearHoverIntentTimer();

    if (dragging) {
      setResolvedHoverIntent(false);
      return;
    }

    setResolvedHoverIntent(true);
  }, [clearHoverIntentTimer, dragging, setResolvedHoverIntent]);

  const hideHoverIntent = useCallback(() => {
    clearHoverIntentTimer();
    setResolvedHoverIntent(false);
  }, [clearHoverIntentTimer, setResolvedHoverIntent]);

  const scheduleHideHoverIntent = useCallback(() => {
    if (!hoverIntentRef.current) {
      return;
    }

    clearHoverIntentTimer();
    hoverIntentTimerRef.current = setTimeout(() => {
      hoverIntentTimerRef.current = null;
      setResolvedHoverIntent(false);
    }, HOVER_HIDE_DELAY_MS);
  }, [clearHoverIntentTimer, setResolvedHoverIntent]);

  const handleHoverPointer = useCallback(
    (event: PointerEvent<HTMLDivElement>) => {
      if (event.pointerType !== "mouse") {
        return;
      }

      const hoverZone = getCanvasNodeHoverZone(
        event.currentTarget,
        event.target
      );

      if (hoverZone === "surface" || hoverZone === "connection") {
        showHoverIntent();
        return;
      }

      if (hoverIntentRef.current && hoverZone === "expand-control") {
        clearHoverIntentTimer();
        setResolvedHoverIntent(true);
        return;
      }

      scheduleHideHoverIntent();
    },
    [
      clearHoverIntentTimer,
      scheduleHideHoverIntent,
      setResolvedHoverIntent,
      showHoverIntent,
    ]
  );

  useEffect(() => {
    if (dragging) {
      hideHoverIntent();
    }
  }, [dragging, hideHoverIntent]);

  useEffect(() => () => clearHoverIntentTimer(), [clearHoverIntentTimer]);

  return (
    <div
      className={cn("canvas-node-frame relative", className)}
      data-connectable={connectable || undefined}
      data-dragging={dragging || undefined}
      data-highlighted-connection-side={highlightedConnectionSide}
      data-hover-intent={hoverIntent || undefined}
      data-selected={selected || undefined}
      data-slot="canvas-node-frame"
      data-state={expanded ? "expanded" : "collapsed"}
      onPointerLeave={scheduleHideHoverIntent}
      onPointerMove={handleHoverPointer}
      onPointerOver={handleHoverPointer}
    >
      {children}
    </div>
  );
}

"use client";

import { cn } from "@workspace/ui/lib/utils";
import { useNodeId } from "@xyflow/react";
import type { ComponentProps } from "react";
import { useCanvasNodeSelfBlur } from "../canvas/canvas-glass-context";

export function CanvasNodeSurface({
  children,
  className,
  ...props
}: ComponentProps<"article">) {
  // When the shared glass sheet handles this node, drop the per-node blur; keep
  // it when there's no sheet or the node overlaps another.
  const selfBlur = useCanvasNodeSelfBlur(useNodeId());
  return (
    <article
      className={cn(
        "canvas-node-surface canvas-node-hover-surface flex min-w-0 flex-col overflow-hidden rounded-lg border-[0.5px] border-border text-zinc-50",
        className
      )}
      data-self-blur={selfBlur ? "" : undefined}
      data-slot="canvas-node-surface"
      {...props}
    >
      {children}
    </article>
  );
}

"use client";

import { cn } from "@workspace/ui/lib/utils";
import type { ComponentProps } from "react";

import { useCanvasNode } from "./canvas-node.context";

export function CanvasNodeHeader({
  className,
  ...props
}: ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "canvas-node-header flex h-auto w-full min-w-0 items-center justify-start text-left font-normal text-zinc-50 transition-[min-height,padding]",
        className
      )}
      data-slot="canvas-node-header"
      {...props}
    />
  );
}

export function CanvasNodeBody({
  children,
  className,
  ...props
}: ComponentProps<"div">) {
  const {
    meta: { expanded },
  } = useCanvasNode();

  return (
    <div
      aria-hidden={expanded ? undefined : true}
      className={cn("canvas-node-body", className)}
      data-slot="canvas-node-body"
      inert={expanded ? undefined : true}
      {...props}
    >
      <div className="canvas-node-body-clip">{children}</div>
    </div>
  );
}

export function CanvasNodeFooter({
  className,
  ...props
}: ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "canvas-node-footer flex w-full min-w-0 items-center justify-between font-normal text-zinc-50",
        className
      )}
      data-slot="canvas-node-footer"
      {...props}
    />
  );
}

"use client";

import type { ReactNode } from "react";

import { CanvasNodeConnectionAnchor } from "./canvas-node.connection";
import { CanvasNodeDragStateFrame } from "./canvas-node.drag-frame";
import { CanvasNodeExpandButton } from "./canvas-node.expand-button";
import { CanvasNodeFrame } from "./canvas-node.frame";
import { CanvasNodeSurface } from "./canvas-node.surface";

export interface CanvasNodeCardProps {
  children?: ReactNode;
  className?: string;
  surfaceClassName?: string;
}

export function CanvasNodeCard({
  children,
  className,
  surfaceClassName,
}: CanvasNodeCardProps) {
  return (
    <CanvasNodeFrame className={className}>
      <CanvasNodeConnectionAnchor />
      <CanvasNodeDragStateFrame>
        <CanvasNodeSurface className={surfaceClassName}>
          {children}
        </CanvasNodeSurface>
      </CanvasNodeDragStateFrame>
      <CanvasNodeExpandButton />
    </CanvasNodeFrame>
  );
}

"use client";

import { cn } from "@workspace/ui/lib/utils";
import type { ComponentProps, ReactNode } from "react";

import { Skeleton } from "../skeleton";
import { CanvasNodeConnectionAnchor } from "./canvas-node.connection";
import { CanvasNodeDragStateFrame } from "./canvas-node.drag-frame";
import { CanvasNodeFrame } from "./canvas-node.frame";
import { CanvasNodeSurface } from "./canvas-node.surface";

export interface CanvasNodePlaceholderProps
  extends Omit<ComponentProps<"article">, "children" | "className"> {
  children?: ReactNode;
  className?: string;
  "data-slot"?: never;
  surfaceClassName?: string;
}

export function CanvasNodePlaceholder({
  children,
  className,
  role = "status",
  surfaceClassName,
  ...props
}: CanvasNodePlaceholderProps) {
  const { "data-slot": _dataSlot, ...surfaceProps } = props;

  return (
    <CanvasNodeFrame className={className}>
      <CanvasNodeConnectionAnchor />
      <CanvasNodeDragStateFrame>
        <CanvasNodeSurface
          className={cn("justify-center p-3", surfaceClassName)}
          role={role}
          {...surfaceProps}
        >
          {children ?? <CanvasNodePlaceholderSkeleton />}
        </CanvasNodeSurface>
      </CanvasNodeDragStateFrame>
    </CanvasNodeFrame>
  );
}

function CanvasNodePlaceholderSkeleton() {
  return (
    <div
      className="flex items-center gap-3"
      data-slot="canvas-node-placeholder"
    >
      <Skeleton className="size-9 shrink-0 rounded-md bg-input" />
      <div className="min-w-0 flex-1 space-y-2">
        <Skeleton className="h-3 w-32 max-w-full bg-input" />
        <Skeleton className="h-2.5 w-44 max-w-full bg-input" />
      </div>
    </div>
  );
}

"use client";

import { cn } from "@workspace/ui/lib/utils";
import { Handle, type HandleType, Position, useNodeId } from "@xyflow/react";
import { Plus } from "lucide-react";
import type { MouseEvent } from "react";

import type { CanvasNodeConnectionSide } from "./canvas-node.types";

const CONNECTION_SIDE_CONFIG = [
  { position: Position.Top, side: "top" },
  { position: Position.Right, side: "right" },
  { position: Position.Bottom, side: "bottom" },
  { position: Position.Left, side: "left" },
] as const satisfies readonly {
  position: Position;
  side: CanvasNodeConnectionSide;
}[];

export interface CanvasNodeConnectionAnchorProps {
  className?: string;
  type?: HandleType;
}

/**
 * Visual per-side connection affordance for CanvasNode.
 *
 * Canvas owns graph behavior (connection mode, draft edge creation, persistence);
 * this component only owns handle placement and hover feedback inside a node shell.
 */
export function CanvasNodeConnectionAnchor({
  className,
  type = "source",
}: CanvasNodeConnectionAnchorProps) {
  const hasNodeContext = useNodeId() != null;

  return (
    <div
      className={cn(
        "canvas-node-connection-anchor pointer-events-none absolute",
        className
      )}
      data-slot="canvas-node-connection-anchor"
    >
      {CONNECTION_SIDE_CONFIG.map(({ position, side }) => (
        <CanvasNodeConnectionSideAnchor
          hasNodeContext={hasNodeContext}
          key={side}
          position={position}
          side={side}
          type={type}
        />
      ))}
    </div>
  );
}

function setFrameHoverSide(
  target: HTMLElement,
  side: CanvasNodeConnectionSide | null
) {
  const frame = target.closest('[data-slot="canvas-node-frame"]');
  if (!(frame instanceof HTMLElement)) {
    return;
  }
  if (side) {
    frame.dataset.hoverSide = side;
  } else {
    delete frame.dataset.hoverSide;
  }
}

function CanvasNodeConnectionSideAnchor({
  hasNodeContext,
  position,
  side,
  type,
}: {
  hasNodeContext: boolean;
  position: Position;
  side: CanvasNodeConnectionSide;
  type: HandleType;
}) {
  return (
    <>
      <CanvasNodeConnectionTarget
        hasNodeContext={hasNodeContext}
        position={position}
        side={side}
        type={type}
      />
      <CanvasNodeConnectionAffordance side={side} />
    </>
  );
}

function CanvasNodeConnectionTarget({
  hasNodeContext,
  position,
  side,
  type,
}: {
  hasNodeContext: boolean;
  position: Position;
  side: CanvasNodeConnectionSide;
  type: HandleType;
}) {
  const handleMouseEnter = (event: MouseEvent<HTMLElement>) => {
    setFrameHoverSide(event.currentTarget, side);
  };
  const handleMouseLeave = (event: MouseEvent<HTMLElement>) => {
    setFrameHoverSide(event.currentTarget, null);
  };
  const targetProps = {
    className:
      "nodrag nopan canvas-node-rf-handle absolute cursor-pointer rounded-full p-0",
    "data-side": side,
    "data-slot": "canvas-node-rf-handle",
    onMouseEnter: handleMouseEnter,
    onMouseLeave: handleMouseLeave,
  };

  if (hasNodeContext) {
    return (
      <Handle
        aria-label={`Connect at ${side}`}
        id={side}
        position={position}
        type={type}
        {...targetProps}
      />
    );
  }

  return <span aria-hidden {...targetProps} />;
}

function CanvasNodeConnectionAffordance({
  side,
}: {
  side: CanvasNodeConnectionSide;
}) {
  return (
    <span
      aria-hidden
      className="canvas-node-connection-affordance pointer-events-none absolute flex items-center justify-center rounded-full"
      data-side={side}
      data-slot="canvas-node-connection-affordance"
    >
      <CanvasNodeConnectionIcon />
    </span>
  );
}

function CanvasNodeConnectionIcon() {
  return <Plus aria-hidden className="canvas-node-connection-icon" size={10} />;
}

