const RF_CONTROL_CLASS = "nodrag nopan";
const CANVAS_NODE_MENU_ALIGN_OFFSET = -10;
const CANVAS_NODE_MENU_SIDE_OFFSET = 14;

export type CanvasNodeActionTone =
  | "default"
  | "destructive"
  | "info"
  | "muted"
  | "success";

export interface CanvasNodeAction {
  disabled?: boolean;
  disabledReason?: string;
  loading?: boolean;
  onClick?: () => Promise<void> | void;
}

export function stopCanvasNodeControlEvent(event: SyntheticEvent) {
  event.stopPropagation();
}

export function invokeCanvasNodeAction(action: CanvasNodeAction | undefined) {
  if (!action?.onClick || action.disabled || action.loading) {
    return;
  }

  Promise.resolve(action.onClick()).catch(() => undefined);
}

export function CanvasNodeActionBar({
  className,
  ...props
}: ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "canvas-node-action-bar mt-2 flex min-w-0 items-center justify-end gap-1",
        className
      )}
      data-slot="canvas-node-action-bar"
      {...props}
    />
  );
}

export interface CanvasNodeActionButtonProps {
  action?: CanvasNodeAction;
  "aria-label": string;
  children?: ReactNode;
  className?: string;
  title?: string;
}

export function CanvasNodeActionButton({
  action,
  "aria-label": ariaLabel,
  children,
  className,
  title,
}: CanvasNodeActionButtonProps) {
  const disabled = action?.disabled || action?.loading || !action?.onClick;
  const disabledReason = disabled ? action?.disabledReason : undefined;
  const tooltip = disabledReason ?? title ?? ariaLabel;
  const button = (
    <AppIconButton
      aria-description={disabledReason}
      aria-disabled={disabled || undefined}
      aria-label={ariaLabel}
      className={cn(
        RF_CONTROL_CLASS,
        "canvas-node-action-button shrink-0 cursor-pointer border-0",
        disabledReason && "cursor-not-allowed opacity-50",
        className
      )}
      disabled={disabled && disabledReason == null}
      onClick={(event) => {
        event.stopPropagation();
        invokeCanvasNodeAction(action);
      }}
      onDoubleClick={stopCanvasNodeControlEvent}
      onKeyDown={stopCanvasNodeControlEvent}
      onPointerDown={stopCanvasNodeControlEvent}
      size="md"
      type="button"
      variant="node"
    >
      {action?.loading ? <Spinner className="size-4" /> : children}
    </AppIconButton>
  );

  return (
    <Tooltip>
      <TooltipTrigger render={button} />
      <TooltipContent>{tooltip}</TooltipContent>
    </Tooltip>
  );
}

export interface CanvasNodeActionMenuProps {
  align?: ComponentProps<typeof DropdownMenuContent>["align"];
  alignOffset?: ComponentProps<typeof DropdownMenuContent>["alignOffset"];
  "aria-label": string;
  children?: ReactNode;
  className?: string;
  contentClassName?: string;
  side?: ComponentProps<typeof DropdownMenuContent>["side"];
  sideOffset?: ComponentProps<typeof DropdownMenuContent>["sideOffset"];
  triggerSize?: AppIconButtonProps["size"];
  triggerVariant?: AppIconButtonProps["variant"];
}

export function CanvasNodeActionMenu({
  align = "start",
  alignOffset = CANVAS_NODE_MENU_ALIGN_OFFSET,
  "aria-label": ariaLabel,
  children,
  className,
  contentClassName,
  side = "right",
  sideOffset = CANVAS_NODE_MENU_SIDE_OFFSET,
  triggerSize = "md",
  triggerVariant = "node",
}: CanvasNodeActionMenuProps) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <AppIconButton
            aria-label={ariaLabel}
            className={cn(
              RF_CONTROL_CLASS,
              "canvas-node-action-menu-trigger shrink-0 cursor-pointer border-0",
              className
            )}
            onClick={stopCanvasNodeControlEvent}
            size={triggerSize}
            type="button"
            variant={triggerVariant}
          >
            <Ellipsis aria-hidden className="size-4" />
          </AppIconButton>
        }
      />
      <DropdownMenuContent
        align={align}
        alignOffset={alignOffset}
        className={cn(
          RF_CONTROL_CLASS,
          "canvas-node-action-menu-content w-38 min-w-38 rounded-md border-0 bg-white/5 p-1 text-zinc-50 shadow-none ring-1 ring-white/10 ring-inset",
          contentClassName
        )}
        side={side}
        sideOffset={sideOffset}
      >
        {children}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export interface CanvasNodeActionMenuItemProps {
  action?: CanvasNodeAction;
  actionKey?: string;
  children?: ReactNode;
  className?: string;
  icon?: ReactNode;
  tone?: CanvasNodeActionTone;
}

export function CanvasNodeActionMenuItem({
  action,
  actionKey,
  children,
  className,
  icon,
  tone = "default",
}: CanvasNodeActionMenuItemProps) {
  const disabled = action?.disabled || action?.loading || !action?.onClick;
  const disabledReason = disabled ? action?.disabledReason : undefined;

  const item = (
    <DropdownMenuItem
      className={cn(
        "canvas-node-action-menu-item h-7 cursor-pointer rounded-md px-2 py-0 font-normal text-sm text-zinc-200 leading-none hover:bg-white/15 hover:text-zinc-50 focus:bg-white/15 focus:text-zinc-50",
        disabledReason &&
          "cursor-not-allowed data-disabled:pointer-events-auto",
        className
      )}
      data-action-key={actionKey}
      data-tone={tone === "default" ? undefined : tone}
      disabled={disabled}
      onClick={(event) => {
        event.stopPropagation();
        invokeCanvasNodeAction(action);
      }}
    >
      {action?.loading ? <Spinner className="size-4" /> : icon}
      {children}
    </DropdownMenuItem>
  );

  if (!disabledReason) {
    return item;
  }

  return (
    <Tooltip>
      <TooltipTrigger render={item} />
      <TooltipContent side="right">{disabledReason}</TooltipContent>
    </Tooltip>
  );
}

"use client";

import { cn } from "@workspace/ui/lib/utils";
import { Check, Copy } from "lucide-react";
import {
  type ComponentPropsWithoutRef,
  createContext,
  type ReactNode,
  type SyntheticEvent,
  use,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

export const CANVAS_NODE_DEFAULT_COPIED_FEEDBACK_MS = 1200;

export type CanvasNodeCopyableRowKey = string;

export interface CanvasNodeCopyFeedbackValue {
  copiedFeedbackMs: number;
  copiedKey: CanvasNodeCopyableRowKey | null;
  showCopiedFeedback: (key: CanvasNodeCopyableRowKey) => void;
}

export type CanvasNodeCopyFeedbackScopeChildren =
  | ReactNode
  | ((value: CanvasNodeCopyFeedbackValue) => ReactNode);

export interface CanvasNodeCopyFeedbackScopeProps {
  children?: CanvasNodeCopyFeedbackScopeChildren;
  copiedFeedbackMs?: number;
  copiedKey?: CanvasNodeCopyableRowKey | null;
}

export interface CanvasNodeCopyableRowState {
  copied: boolean;
  copyable: boolean;
  /**
   * Runs the row's copy action — the injected onCopy or the clipboard
   * fallback — followed by copied feedback, exactly like the row hit-area.
   * Lets custom controls inside the row copy without a second pipeline.
   */
  copyRow: () => Promise<void>;
}

type CanvasNodeCopyableRowChildren =
  | ReactNode
  | ((state: CanvasNodeCopyableRowState) => ReactNode);

export interface CanvasNodeCopyableRowProps
  extends Omit<ComponentPropsWithoutRef<"section">, "children" | "onCopy"> {
  children?: CanvasNodeCopyableRowChildren;
  copyAriaLabel: string;
  copyable?: boolean;
  copyValue?: string;
  onCopy?: (
    value: string,
    key: CanvasNodeCopyableRowKey
  ) => Promise<void> | void;
  rowKey: CanvasNodeCopyableRowKey;
}

export type CanvasNodeCopyableRowControlProps =
  ComponentPropsWithoutRef<"span">;

export type CanvasNodeCopyableRowIndicatorProps =
  ComponentPropsWithoutRef<"span">;

const CanvasNodeCopyFeedbackContext =
  createContext<CanvasNodeCopyFeedbackValue | null>(null);

const CanvasNodeCopyableRowContext =
  createContext<CanvasNodeCopyableRowState | null>(null);

async function copyTextToClipboard(value: string) {
  if (typeof navigator === "undefined" || !navigator.clipboard) {
    return;
  }

  await navigator.clipboard.writeText(value);
}

function stopCanvasNodeControlEvent(event: SyntheticEvent) {
  event.stopPropagation();
}

function composeStopPropagationHandler<Event extends SyntheticEvent>(
  handler: ((event: Event) => void) | undefined
) {
  return (event: Event) => {
    handler?.(event);
    stopCanvasNodeControlEvent(event);
  };
}

function renderCopyFeedbackChildren(
  children: CanvasNodeCopyFeedbackScopeChildren | undefined,
  value: CanvasNodeCopyFeedbackValue
) {
  if (typeof children === "function") {
    return children(value);
  }

  return children;
}

function renderCopyableRowChildren(
  children: CanvasNodeCopyableRowChildren | undefined,
  state: CanvasNodeCopyableRowState
) {
  if (typeof children === "function") {
    return children(state);
  }

  return children;
}

export function CanvasNodeCopyFeedbackScope({
  children,
  copiedFeedbackMs = CANVAS_NODE_DEFAULT_COPIED_FEEDBACK_MS,
  copiedKey,
}: CanvasNodeCopyFeedbackScopeProps) {
  const [internalCopiedKey, setInternalCopiedKey] =
    useState<CanvasNodeCopyableRowKey | null>(null);
  const resetTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const copiedKeyControlled = copiedKey !== undefined;
  const resolvedCopiedKey = copiedKeyControlled ? copiedKey : internalCopiedKey;

  useEffect(
    () => () => {
      if (resetTimerRef.current) {
        clearTimeout(resetTimerRef.current);
      }
    },
    []
  );

  const showCopiedFeedback = useCallback(
    (nextCopiedKey: CanvasNodeCopyableRowKey) => {
      if (copiedKeyControlled) {
        return;
      }

      setInternalCopiedKey(nextCopiedKey);

      if (resetTimerRef.current) {
        clearTimeout(resetTimerRef.current);
      }

      resetTimerRef.current = setTimeout(() => {
        setInternalCopiedKey(null);
        resetTimerRef.current = null;
      }, copiedFeedbackMs);
    },
    [copiedFeedbackMs, copiedKeyControlled]
  );

  const value = useMemo(
    (): CanvasNodeCopyFeedbackValue => ({
      copiedFeedbackMs,
      copiedKey: resolvedCopiedKey ?? null,
      showCopiedFeedback,
    }),
    [copiedFeedbackMs, resolvedCopiedKey, showCopiedFeedback]
  );

  return (
    <CanvasNodeCopyFeedbackContext value={value}>
      {renderCopyFeedbackChildren(children, value)}
    </CanvasNodeCopyFeedbackContext>
  );
}

export function useCanvasNodeCopyFeedback(): CanvasNodeCopyFeedbackValue {
  const value = use(CanvasNodeCopyFeedbackContext);

  if (!value) {
    throw new Error(
      "CanvasNode.CopyableRow must be used within CanvasNode.CopyFeedbackScope"
    );
  }

  return value;
}

export function useCanvasNodeCopyableRow(): CanvasNodeCopyableRowState {
  const value = use(CanvasNodeCopyableRowContext);

  if (!value) {
    throw new Error(
      "CanvasNode.CopyableRowIndicator must be used within CanvasNode.CopyableRow"
    );
  }

  return value;
}

export function CanvasNodeCopyableRow({
  children,
  className,
  copyAriaLabel,
  copyValue,
  copyable,
  onCopy,
  rowKey,
  title,
  ...props
}: CanvasNodeCopyableRowProps) {
  const { copiedKey, showCopiedFeedback } = useCanvasNodeCopyFeedback();
  const hasCopyValue = typeof copyValue === "string" && copyValue.length > 0;
  const resolvedCopyable = (copyable ?? hasCopyValue) && hasCopyValue;

  const copyRow = useCallback(async () => {
    if (!(resolvedCopyable && copyValue)) {
      return;
    }

    // Feedback follows the copy: an onCopy handler may fetch the real value
    // on demand, and a rejected copy must not read as "copied".
    if (onCopy) {
      await onCopy(copyValue, rowKey);
    } else {
      await copyTextToClipboard(copyValue);
    }
    showCopiedFeedback(rowKey);
  }, [copyValue, onCopy, resolvedCopyable, rowKey, showCopiedFeedback]);

  const state = useMemo(
    (): CanvasNodeCopyableRowState => ({
      copied: copiedKey === rowKey,
      copyable: resolvedCopyable,
      copyRow,
    }),
    [copiedKey, copyRow, resolvedCopyable, rowKey]
  );

  return (
    <CanvasNodeCopyableRowContext value={state}>
      <section
        className={cn(
          "group/copyable-row canvas-node-copyable-row",
          !resolvedCopyable && "canvas-node-copyable-row-static",
          className
        )}
        data-copied={state.copied ? "true" : undefined}
        data-copyable={resolvedCopyable || undefined}
        data-slot="canvas-node-copyable-row"
        {...props}
      >
        {resolvedCopyable ? (
          <button
            aria-label={copyAriaLabel}
            className="nodrag nopan canvas-node-copyable-row-hitarea absolute inset-0 z-0 cursor-pointer rounded-lg focus-visible:outline-none"
            data-slot="canvas-node-copyable-row-hitarea"
            onClick={(event) => {
              event.stopPropagation();
              copyRow().catch(() => undefined);
            }}
            onDoubleClick={stopCanvasNodeControlEvent}
            onKeyDown={stopCanvasNodeControlEvent}
            onPointerDown={stopCanvasNodeControlEvent}
            title={title ?? copyValue}
            type="button"
          />
        ) : null}
        {renderCopyableRowChildren(children, state)}
      </section>
    </CanvasNodeCopyableRowContext>
  );
}

export function CanvasNodeCopyableRowControl({
  children,
  className,
  onClick,
  onDoubleClick,
  onKeyDown,
  onPointerDown,
  ...props
}: CanvasNodeCopyableRowControlProps) {
  return (
    // biome-ignore lint/a11y/noNoninteractiveElementInteractions: wrapper isolates nested controls from React Flow drag and pan events.
    // biome-ignore lint/a11y/noStaticElementInteractions: interaction remains on nested controls; this span only stops propagation.
    <span
      className={cn("nodrag nopan", className)}
      onClick={composeStopPropagationHandler(onClick)}
      onDoubleClick={composeStopPropagationHandler(onDoubleClick)}
      onKeyDown={composeStopPropagationHandler(onKeyDown)}
      onPointerDown={composeStopPropagationHandler(onPointerDown)}
      {...props}
    >
      {children}
    </span>
  );
}

export function CanvasNodeCopyableRowIndicator({
  className,
  ...props
}: CanvasNodeCopyableRowIndicatorProps) {
  const { copied, copyable } = useCanvasNodeCopyableRow();

  if (!copyable) {
    return null;
  }

  if (copied) {
    return (
      <span
        className={cn("size-4 shrink-0", className)}
        key="copied"
        {...props}
      >
        <Check aria-hidden className="size-4" />
      </span>
    );
  }

  return (
    <span
      className={cn(
        "canvas-node-copyable-row-copy-icon size-4 shrink-0 opacity-0 transition-opacity group-hover/copyable-row:opacity-100",
        className
      )}
      key="copy"
      {...props}
    >
      <Copy aria-hidden className="size-4" />
    </span>
  );
}

"use client";

import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@workspace/ui/components/tooltip";
import { cn } from "@workspace/ui/lib/utils";
import type { ReactNode, SyntheticEvent } from "react";

import { useCanvasNodeCopyableRow } from "./canvas-node.copyable-row";

export interface CanvasNodeCopyableRowValueProps {
  children?: ReactNode;
  className?: string;
  /** Candidate URL; the value renders as a link only when http(s). */
  href?: string;
}

/**
 * Returns the normalized href when the value is an absolute http(s) URL,
 * undefined otherwise — placeholder values like "Pending" render no link.
 */
export function canvasNodeOpenHref(
  value: string | undefined
): string | undefined {
  const trimmed = value?.trim() ?? "";
  if (trimmed === "") {
    return undefined;
  }
  try {
    const parsed = new URL(trimmed);
    return parsed.protocol === "http:" || parsed.protocol === "https:"
      ? parsed.href
      : undefined;
  } catch {
    return undefined;
  }
}

function stopRowEvent(event: SyntheticEvent) {
  event.stopPropagation();
}

/**
 * The value text of a copyable row. An http(s) value renders as a new-tab
 * link that underlines on hover, shows the full value in a tooltip, and
 * stays isolated from the row copy hit-area and canvas drag; other values
 * render as plain text covered by the row's copy control.
 */
export function CanvasNodeCopyableRowValue({
  children,
  className,
  href,
}: CanvasNodeCopyableRowValueProps) {
  const { copyable } = useCanvasNodeCopyableRow();
  const openHref = canvasNodeOpenHref(href);

  if (openHref === undefined) {
    return (
      <span
        aria-hidden={copyable ? true : undefined}
        className={cn("min-w-0 truncate", className)}
        data-slot="canvas-node-row-value"
      >
        {children}
      </span>
    );
  }

  const link = (
    <a
      className={cn(
        "nodrag nopan pointer-events-auto relative min-w-0 cursor-pointer truncate rounded-xs underline-offset-2 outline-none hover:underline focus-visible:underline focus-visible:ring-[3px] focus-visible:ring-ring/50",
        className
      )}
      data-slot="canvas-node-row-value"
      href={openHref}
      onClick={stopRowEvent}
      onDoubleClick={stopRowEvent}
      onKeyDown={stopRowEvent}
      onPointerDown={stopRowEvent}
      rel="noopener noreferrer"
      target="_blank"
    >
      {children}
    </a>
  );

  return (
    <Tooltip>
      <TooltipTrigger render={link} />
      <TooltipContent>{children}</TooltipContent>
    </Tooltip>
  );
}

"use client";

import { AppIconButton } from "@workspace/ui/components/app-icon-button";
import { cn } from "@workspace/ui/lib/utils";
import { Check, Copy } from "lucide-react";

import {
  CanvasNodeCopyableRowControl,
  useCanvasNodeCopyableRow,
} from "./canvas-node.copyable-row";

export interface CanvasNodeCopyableRowActionsProps {
  className?: string;
  /** Row subject used in control labels, e.g. "Platform Address". */
  label: string;
}

/**
 * The action cluster for a copyable row: an explicit copy button routed
 * through the row's copy pipeline. Controls surface on row hover/focus and
 * stay pinned during copied feedback.
 */
export function CanvasNodeCopyableRowActions({
  className,
  label,
}: CanvasNodeCopyableRowActionsProps) {
  const { copied, copyable, copyRow } = useCanvasNodeCopyableRow();

  if (!copyable) {
    return null;
  }

  return (
    <CanvasNodeCopyableRowControl
      className={cn(
        "pointer-events-auto relative z-20 -mr-1.5 flex shrink-0 items-center gap-0.5 transition-opacity",
        copied
          ? "opacity-100"
          : "opacity-0 group-focus-within/copyable-row:opacity-100 group-hover/copyable-row:opacity-100",
        className
      )}
      data-slot="canvas-node-row-actions"
    >
      <AppIconButton
        aria-label={`${copied ? "Copied" : "Copy"} ${label}`}
        className={cn(
          "text-muted-foreground hover:text-foreground",
          copied && "text-foreground"
        )}
        data-slot="canvas-node-row-copy-button"
        onClick={() => {
          copyRow().catch(() => undefined);
        }}
        size="sm"
        type="button"
        variant="quiet"
      >
        {copied ? (
          <Check aria-hidden className="size-4" />
        ) : (
          <Copy aria-hidden className="size-4" />
        )}
      </AppIconButton>
    </CanvasNodeCopyableRowControl>
  );
}

"use client";

import NumberFlow from "@number-flow/react";
import { cn } from "@workspace/ui/lib/utils";
import type { ComponentProps, ComponentType, ReactNode, SVGProps } from "react";

import {
  CanvasNodeStatusDot,
  DEFAULT_CANVAS_NODE_STATUS,
  getCanvasNodeStatusTextClassName,
  resolveCanvasNodeStatus,
} from "./canvas-node.status";
import type { CanvasNodeStatus } from "./canvas-node.types";

export type CanvasNodeMetricValue = number | string | undefined;

export type CanvasNodeMetricValueFormat = "default" | "percent";

export type CanvasNodeMetricRecord<Key extends string = string> = Partial<
  Record<Key, CanvasNodeMetricValue>
>;

export interface CanvasNodeMetricListItem<Key extends string = string> {
  format?: CanvasNodeMetricValueFormat;
  icon: ComponentType<SVGProps<SVGSVGElement>>;
  key: Key;
  label: string;
}

export interface CanvasNodeMetricListProps<Key extends string = string>
  extends Omit<ComponentProps<"div">, "children"> {
  children?: ReactNode;
  items: readonly CanvasNodeMetricListItem<Key>[];
  valueFormat?: CanvasNodeMetricValueFormat;
  values?: CanvasNodeMetricRecord<Key>;
}

const CANVAS_NODE_METRIC_PERCENT_FORMATTER = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 0,
});

const CANVAS_NODE_METRIC_PERCENT_PATTERN = /^(-?\d+(?:\.\d+)?)\s*%$/;
const CANVAS_NODE_RESOURCE_PRESSURE_ELEVATED_THRESHOLD = 75;
const CANVAS_NODE_RESOURCE_PRESSURE_CRITICAL_THRESHOLD = 90;

function formatCanvasNodeMetricPercent(value: number) {
  return Number.isFinite(value)
    ? `${CANVAS_NODE_METRIC_PERCENT_FORMATTER.format(value)}%`
    : "--";
}

function parseCanvasNodeMetricPercentValue(
  value: CanvasNodeMetricValue
): number | undefined {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : undefined;
  }

  const trimmed = value?.trim();
  if (!trimmed) {
    return undefined;
  }

  const percentMatch = CANVAS_NODE_METRIC_PERCENT_PATTERN.exec(trimmed);
  const n = percentMatch ? Number(percentMatch[1]) : Number(trimmed);

  return Number.isFinite(n) ? n : undefined;
}

function getCanvasNodeResourcePressureTextClassName(value: number) {
  if (value > CANVAS_NODE_RESOURCE_PRESSURE_CRITICAL_THRESHOLD) {
    return "text-red-500";
  }

  if (value >= CANVAS_NODE_RESOURCE_PRESSURE_ELEVATED_THRESHOLD) {
    return "text-amber-500";
  }

  return "text-muted-foreground";
}

function getCanvasNodeMetricTextClassName(
  format: CanvasNodeMetricValueFormat | undefined,
  percentValue: number | undefined
) {
  if (format !== "percent") {
    return "text-muted-foreground";
  }

  if (percentValue === undefined) {
    return "text-muted-foreground";
  }

  return getCanvasNodeResourcePressureTextClassName(percentValue);
}

export function formatCanvasNodeMetricValue(
  value: CanvasNodeMetricValue,
  format: CanvasNodeMetricValueFormat = "default"
) {
  if (format === "percent") {
    const percentValue = parseCanvasNodeMetricPercentValue(value);
    if (percentValue !== undefined) {
      return formatCanvasNodeMetricPercent(percentValue);
    }

    return typeof value === "string" ? value.trim() || "--" : "--";
  }

  if (typeof value === "number") {
    return String(value);
  }

  const trimmed = value?.trim();

  return trimmed || "--";
}

export function CanvasNodeFooterStatus({
  className,
  status = DEFAULT_CANVAS_NODE_STATUS,
}: {
  className?: string;
  status?: CanvasNodeStatus;
}) {
  const resolvedStatus = resolveCanvasNodeStatus(status);

  return (
    <span
      className={cn(
        "flex h-5 min-w-0 shrink-0 items-center gap-1.5 rounded-full",
        className
      )}
    >
      <CanvasNodeStatusDot size="small" status={resolvedStatus} />
      <span
        className={cn("truncate", getCanvasNodeStatusTextClassName(status))}
      >
        {resolvedStatus.label}
      </span>
    </span>
  );
}

export function CanvasNodeMetrics({
  className,
  ...props
}: ComponentProps<"div">) {
  return (
    <div
      className={cn(
        "flex min-w-0 items-center justify-end gap-2 text-xs leading-none",
        className
      )}
      data-slot="canvas-node-metrics"
      {...props}
    />
  );
}

export function CanvasNodeMetric({
  children,
  className,
  format,
  label,
  value,
}: {
  children?: ReactNode;
  className?: string;
  format?: CanvasNodeMetricValueFormat;
  label: string;
  value: CanvasNodeMetricValue;
}) {
  const formattedValue = formatCanvasNodeMetricValue(value, format);
  const percentValue =
    format === "percent" ? parseCanvasNodeMetricPercentValue(value) : undefined;
  const metricTextClassName = getCanvasNodeMetricTextClassName(
    format,
    percentValue
  );

  return (
    <span
      className={cn(
        "flex h-5 min-w-0 shrink-0 items-center rounded-full transition-colors duration-200",
        metricTextClassName,
        className
      )}
    >
      <span className="sr-only">{`${label}: ${formattedValue}`}</span>
      <span aria-hidden className="flex min-w-0 shrink-0 items-center gap-1.5">
        {children}
        {percentValue === undefined ? (
          <span className="truncate tabular-nums">{formattedValue}</span>
        ) : (
          <NumberFlow
            className="truncate tabular-nums"
            format={{
              maximumFractionDigits: 0,
              style: "percent",
            }}
            isolate
            locales="en-US"
            value={percentValue / 100}
          />
        )}
      </span>
    </span>
  );
}

export function CanvasNodeMetricList<Key extends string = string>({
  children,
  className,
  items,
  valueFormat = "percent",
  values,
  ...props
}: CanvasNodeMetricListProps<Key>) {
  return (
    <CanvasNodeMetrics className={className} {...props}>
      {items.map((item) => {
        const Icon = item.icon;

        return (
          <CanvasNodeMetric
            format={item.format ?? valueFormat}
            key={item.key}
            label={item.label}
            value={values?.[item.key]}
          >
            <Icon aria-hidden className="size-3.5 shrink-0" />
          </CanvasNodeMetric>
        );
      })}
      {children}
    </CanvasNodeMetrics>
  );
}

.canvas-node-frame {
  --canvas-node-surface-base: color-mix(
    in oklab,
    var(--color-white) 4.5%,
    transparent
  );
  --canvas-node-surface-active-bg: transparent;
  --canvas-node-card-width: calc(var(--spacing) * 68);
  --canvas-node-card-height-collapsed: calc(var(--spacing) * 15.5);
  --canvas-node-control-size: calc(var(--spacing) * 8);
  --canvas-node-control-gap: calc(var(--spacing) * 1.5);
  --canvas-node-connection-size: calc(var(--spacing) * 5);
  --canvas-node-connection-gap: calc(var(--spacing) * 1.5);
  --canvas-node-connection-hit-size: var(--canvas-node-connection-size);
  --canvas-node-edge-highlight-size: calc(var(--spacing) * 0.25);
  display: grid;
  grid-template-columns: var(--canvas-node-card-width);
  align-items: start;
  width: var(--canvas-node-card-width);
  min-height: var(--canvas-node-card-height-collapsed);
  cursor: default;
  transition: min-height 180ms cubic-bezier(0.16, 1, 0.3, 1);
}

.canvas-node-frame:is([data-hover-intent], [data-dragging], [data-selected]) {
  --canvas-node-surface-active-bg: color-mix(
    in oklab,
    var(--color-zinc-950) 20%,
    transparent
  );
}

.canvas-node-surface {
  grid-row: 1;
  grid-column: 1;
  width: var(--canvas-node-card-width);
  min-height: var(--canvas-node-card-height-collapsed);
  background:
    linear-gradient(
      90deg,
      var(--canvas-node-surface-base) 0%,
      var(--canvas-node-surface-base) 100%
    ),
    linear-gradient(
      90deg,
      var(--canvas-node-surface-active-bg) 0%,
      var(--canvas-node-surface-active-bg) 100%
    );
  transition:
    background 150ms ease-out,
    border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}

/* Per-node backdrop blur. Present by default; the shared glass sheet
   drops it for isolated nodes and restores it for overlapping ones by toggling
   data-self-blur. Uses --canvas-glass-blur-radius so it matches the sheet. */
.canvas-node-surface[data-self-blur] {
  -webkit-backdrop-filter: blur(var(--canvas-glass-blur-radius, 40px));
  backdrop-filter: blur(var(--canvas-glass-blur-radius, 40px));
}

.react-flow__node.draggable .canvas-node-surface {
  cursor: default;
}

.react-flow__node.draggable.dragging .canvas-node-surface {
  cursor: grabbing;
}

.canvas-node-frame:is([data-dragging], [data-selected]) .canvas-node-surface {
  border-color: var(--color-blue-400);
}

.canvas-node-frame[data-hover-side="top"] .canvas-node-surface {
  box-shadow: 0 calc(var(--canvas-node-edge-highlight-size) * -1) 0 0
    var(--color-blue-400);
}

.canvas-node-frame[data-hover-side="right"] .canvas-node-surface {
  box-shadow: var(--canvas-node-edge-highlight-size) 0 0 0 var(--color-blue-400);
}

.canvas-node-frame[data-hover-side="bottom"] .canvas-node-surface {
  box-shadow: 0 var(--canvas-node-edge-highlight-size) 0 0 var(--color-blue-400);
}

.canvas-node-frame[data-hover-side="left"] .canvas-node-surface {
  box-shadow: calc(var(--canvas-node-edge-highlight-size) * -1) 0 0 0
    var(--color-blue-400);
}

.canvas-node-frame[data-highlighted-connection-side="top"]
  .canvas-node-surface {
  box-shadow: 0 calc(var(--canvas-node-edge-highlight-size) * -1) 0 0
    var(--color-blue-400);
}

.canvas-node-frame[data-highlighted-connection-side="right"]
  .canvas-node-surface {
  box-shadow: var(--canvas-node-edge-highlight-size) 0 0 0 var(--color-blue-400);
}

.canvas-node-frame[data-highlighted-connection-side="bottom"]
  .canvas-node-surface {
  box-shadow: 0 var(--canvas-node-edge-highlight-size) 0 0 var(--color-blue-400);
}

.canvas-node-frame[data-highlighted-connection-side="left"]
  .canvas-node-surface {
  box-shadow: calc(var(--canvas-node-edge-highlight-size) * -1) 0 0 0
    var(--color-blue-400);
}

.canvas-node-header {
  min-height: var(--canvas-node-card-height-collapsed);
  padding: calc(var(--spacing) * 2.5);
  border-bottom: 0.5px solid transparent;
  transition: border-color 150ms ease-out;
}

.canvas-node-frame[data-state="expanded"] .canvas-node-header {
  border-bottom-color: color-mix(in oklab, var(--color-white) 10%, transparent);
}

.canvas-node-header-content {
  display: flex;
  flex-direction: column;
}

.canvas-node-body {
  display: grid;
  grid-template-rows: 0fr;
  overflow: hidden;
  opacity: 0;
  transition:
    grid-template-rows 150ms cubic-bezier(0.16, 1, 0.3, 1),
    opacity 100ms ease;
}

.canvas-node-frame[data-state="expanded"] .canvas-node-body {
  grid-template-rows: 1fr;
  opacity: 1;
  transition-delay: 40ms, 40ms;
  transition-duration: 180ms, 120ms;
}

.canvas-node-body-clip {
  min-height: 0;
  padding: 0 calc(var(--spacing) * 2.5);
  overflow: hidden;
  transition: padding-bottom 150ms cubic-bezier(0.16, 1, 0.3, 1);
}

.canvas-node-frame[data-state="expanded"] .canvas-node-body-clip {
  padding-bottom: calc(var(--spacing) * 2.5);
  transition-delay: 40ms;
  transition-duration: 180ms;
}

.canvas-node-footer {
  min-height: calc(var(--spacing) * 10);
  padding: calc(var(--spacing) * 2.5);
  border-top: 0.5px solid
    color-mix(in oklab, var(--color-white) 10%, transparent);
}

.canvas-node-copyable-row[data-copyable]:hover,
.canvas-node-copyable-row:has(.canvas-node-copyable-row-hitarea:focus-visible) {
  background: color-mix(in oklab, var(--color-white) 4.5%, transparent);
}

.canvas-node-connection-anchor {
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  width: var(--canvas-node-card-width);
}

.react-flow__handle.canvas-node-rf-handle[data-side] {
  width: var(--canvas-node-connection-hit-size);
  height: var(--canvas-node-connection-hit-size);
  overflow: visible;
  pointer-events: none;
  background: transparent;
  border: 0;
  border-radius: 0;
  opacity: 0;
  transform: none;
  transition: opacity 150ms ease;
}

.canvas-node-connection-affordance {
  width: var(--canvas-node-connection-size);
  height: var(--canvas-node-connection-size);
  opacity: 0;
  transition: opacity 150ms ease;
}

.canvas-node-connection-affordance::after {
  position: absolute;
  inset: 0;
  content: "";
  background:
    linear-gradient(
      90deg,
      var(--canvas-node-surface-base) 0%,
      var(--canvas-node-surface-base) 100%
    ),
    linear-gradient(
      90deg,
      color-mix(in oklab, var(--color-zinc-950) 20%, transparent) 0%,
      color-mix(in oklab, var(--color-zinc-950) 20%, transparent) 100%
    );
  border: 0.5px solid color-mix(in oklab, var(--color-white) 10%, transparent);
  border-radius: inherit;
  backdrop-filter: blur(8px);
  transform-origin: center;
  scale: 0.4;
  transition:
    scale 150ms ease,
    background 150ms ease,
    border 150ms ease;
}

.canvas-node-frame[data-state="expanded"]:not([data-dragging]):is(
    [data-hover-intent],
    [data-selected]
  )
  .react-flow__handle.canvas-node-rf-handle {
  opacity: 1;
}

.react-flow.project-canvas-connection-active
  .canvas-node-frame[data-connectable][data-state="expanded"]:not(
    [data-dragging]
  )
  .react-flow__handle.canvas-node-rf-handle.connectionindicator[data-side],
.canvas-node-frame[data-connectable][data-state="expanded"]:not([data-dragging])
  .react-flow__handle.canvas-node-rf-handle[data-side] {
  pointer-events: auto;
}

.canvas-node-frame[data-connectable][data-state="expanded"]:not(
    [data-dragging]
  ):is([data-hover-intent], [data-selected])
  .canvas-node-connection-affordance {
  opacity: 1;
}

.canvas-node-frame[data-connectable][data-state="expanded"]:not([data-dragging])
  .react-flow__handle.canvas-node-rf-handle:hover
  + .canvas-node-connection-affordance {
  opacity: 1;
}

.react-flow__handle.canvas-node-rf-handle:hover
  + .canvas-node-connection-affordance::after {
  background: color-mix(in oklab, var(--color-white) 5%, transparent);
  border: 1px solid var(--color-blue-400);
  scale: 1;
}

.canvas-node-connection-icon {
  position: relative;
  z-index: 1;
  color: var(--color-zinc-50);
  opacity: 0;
  transition: opacity 150ms ease;
}

.react-flow__handle.canvas-node-rf-handle:hover
  + .canvas-node-connection-affordance
  .canvas-node-connection-icon {
  opacity: 1;
}

.react-flow__handle.canvas-node-rf-handle[data-side="top"] {
  top: 0;
  left: 0;
  width: 100%;
  translate: 0 -50%;
}

.react-flow__handle.canvas-node-rf-handle[data-side="right"] {
  top: 50%;
  right: 0;
  height: max(
    var(--canvas-node-connection-size),
    calc(100% - (var(--canvas-node-connection-hit-size) * 2))
  );
  translate: 50% -50%;
}

.react-flow__handle.canvas-node-rf-handle[data-side="bottom"] {
  bottom: 0;
  left: 0;
  width: 100%;
  translate: 0 50%;
}

.react-flow__handle.canvas-node-rf-handle[data-side="left"] {
  top: 50%;
  left: 0;
  height: max(
    var(--canvas-node-connection-size),
    calc(100% - (var(--canvas-node-connection-hit-size) * 2))
  );
  translate: -50% -50%;
}

.canvas-node-connection-affordance[data-side="top"] {
  top: 0;
  left: 50%;
  translate: -50% calc(-100% - var(--canvas-node-connection-gap));
}

.canvas-node-connection-affordance[data-side="right"] {
  top: 50%;
  right: 0;
  translate: calc(100% + var(--canvas-node-connection-gap)) -50%;
}

.canvas-node-connection-affordance[data-side="bottom"] {
  bottom: 0;
  left: 50%;
  translate: -50% calc(100% + var(--canvas-node-connection-gap));
}

.canvas-node-connection-affordance[data-side="left"] {
  top: 50%;
  left: 0;
  translate: calc(-100% - var(--canvas-node-connection-gap)) -50%;
}

/* Plain action buttons only — deliberately NOT the menu trigger. The trigger's
   hover/open background is owned by the AppIconButton `node` variant
   (hover:bg-input / data-popup-open:bg-input). This rule is unlayered, so it
   would beat the layered variant utilities: re-adding the trigger here flips an
   open menu button back to this subtle bg on hover (the "weird" background jump). */
.canvas-node-action-button:hover,
.canvas-node-action-button:focus-visible {
  background: color-mix(in oklab, var(--color-white) 4.5%, transparent);
}

.canvas-node-action-button:is([data-state="open"], [data-popup-open]) {
  color: var(--sealai-brand-primary-foreground);
}

.canvas-node-action-button:is([data-state="open"], [data-popup-open]):not(
    :hover,
    :focus-visible
  ) {
  background: color-mix(in oklab, var(--color-zinc-950) 20%, transparent);
}

.canvas-node-action-menu-content {
  backdrop-filter: blur(calc(var(--spacing) * 5));
}

.canvas-node-action-menu-item[data-highlighted] {
  color: var(--color-zinc-50);
  background: color-mix(in oklab, var(--color-white) 15%, transparent);
}

.canvas-node-action-menu-item:is(
    :hover,
    :focus,
    [data-highlighted]
  )[data-tone="info"]
  svg {
  color: var(--color-blue-400);
  stroke: var(--color-blue-400);
}

.canvas-node-action-menu-item:is(
    :hover,
    :focus,
    [data-highlighted]
  )[data-tone="destructive"]
  svg {
  color: var(--color-red-500);
  stroke: var(--color-red-500);
}

.canvas-node-action-menu-item:is(
    :hover,
    :focus,
    [data-highlighted]
  )[data-tone="muted"]
  svg {
  color: var(--muted-foreground);
  stroke: var(--muted-foreground);
}

.canvas-node-action-menu-item:is(
    :hover,
    :focus,
    [data-highlighted]
  )[data-tone="success"]
  svg {
  color: var(--color-green-500);
  stroke: var(--color-green-500);
}

.canvas-node-card-frame {
  position: relative;
  grid-row: 1;
  grid-column: 1;
}

.canvas-node-card-frame::before {
  position: absolute;
  inset: calc(var(--spacing) * -1);
  pointer-events: none;
  content: "";
  background: var(--canvas-node-surface-base);
  border-radius: inherit;
  opacity: 0;
  transition: opacity 150ms ease-out;
}

.canvas-node-frame:is([data-hover-intent], [data-dragging])
  .canvas-node-card-frame::before {
  opacity: 1;
}

.canvas-node-drag-frame::after {
  --canvas-node-drag-stroke: color-mix(
    in oklab,
    var(--color-white) 15%,
    transparent
  );
  --canvas-node-drag-stroke-clear: transparent;
  position: absolute;
  inset: -4px;
  padding: 1px;
  pointer-events: none;
  content: "";
  background:
    linear-gradient(
      135deg,
      var(--canvas-node-drag-stroke) 0%,
      var(--canvas-node-drag-stroke-clear) 18%
    ),
    linear-gradient(
      135deg,
      var(--canvas-node-drag-stroke) 0%,
      var(--canvas-node-drag-stroke-clear) 18%
    ),
    linear-gradient(
      315deg,
      var(--canvas-node-drag-stroke) 0%,
      var(--canvas-node-drag-stroke-clear) 18%
    ),
    linear-gradient(
      315deg,
      var(--canvas-node-drag-stroke) 0%,
      var(--canvas-node-drag-stroke-clear) 18%
    );
  border-radius: inherit;
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
}

.canvas-node-expand-button[data-variant="node"] {
  --canvas-node-expand-underlay: transparent;
  position: absolute;
  top: 0;
  left: calc(
    -1 *
    (var(--canvas-node-control-size) + var(--canvas-node-control-gap))
  );
  width: var(--canvas-node-control-size);
  height: var(--canvas-node-control-size);
  color: var(--sealai-brand-primary-foreground);
  pointer-events: none;
  cursor: pointer;
  background:
    linear-gradient(
      90deg,
      var(--canvas-node-surface-base) 0%,
      var(--canvas-node-surface-base) 100%
    ),
    linear-gradient(
      90deg,
      var(--canvas-node-expand-underlay) 0%,
      var(--canvas-node-expand-underlay) 100%
    );
  opacity: 0;
  transition:
    opacity 150ms ease,
    background 150ms ease,
    color 150ms ease;
}

.canvas-node-frame:not([data-dragging]):is([data-hover-intent], [data-selected])
  .canvas-node-expand-button[data-variant="node"] {
  pointer-events: auto;
  opacity: 1;
}

.canvas-node-expand-button[data-variant="node"]:hover {
  --canvas-node-expand-underlay: var(--canvas-node-surface-active-bg);
  color: var(--color-blue-400);
}

